"use client";

import { usePathname } from "next/navigation";
import CharitySidebar from "./CharitySidebar";
import { useState, useEffect } from "react";
import { Menu } from "lucide-react";
import DeveloperRoleSwitcher from "@/components/DeveloperRoleSwitcher";
import { MAIL_UNREAD_EVENT } from "@/lib/mailBadge";
import { getPortalUnreadCount } from "@/app/actions/charityMail";

export default function CharityLayoutClient({
  children,
  charityName,
  logoUrl,
  role,
  userType,
  availableCharities = [],
  isDeveloper,
  currentEmployeeId,
  permissions = [],
  title,
  isAdmin = false,
  unreadMail = 0,
}: {
  children: React.ReactNode;
  charityName: string;
  logoUrl: string | null;
  role?: string;
  userType?: string;
  availableCharities?: { id: string, name: string }[];
  isDeveloper?: boolean;
  currentEmployeeId?: string;
  permissions?: string[];
  title?: string;
  isAdmin?: boolean;
  unreadMail?: number;
}) {
  const pathname = usePathname();
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // الشريط يبقى مركّباً عبر التنقّل، فلا يُعاد رسمه حين تُقرأ رسالة. وصفحة
  // البريد تقول «تغيّر شيء»، فيُعاد قراءة العدد الذي يعرف كيف يجلبه.
  const [unread, setUnread] = useState(unreadMail);
  useEffect(() => {
    let active = true;
    const refresh = () => {
      getPortalUnreadCount(charityName)
        .then((count) => {
          if (active) setUnread(count);
        })
        // فشل الجلب يُبقي آخر عددٍ معروف: أصدق من تصفيره وادّعاء أن لا جديد.
        .catch(() => {});
    };
    window.addEventListener(MAIL_UNREAD_EVENT, refresh);
    return () => {
      active = false;
      window.removeEventListener(MAIL_UNREAD_EVENT, refresh);
    };
  }, [charityName]);



  // Close sidebar on mobile when navigating
  useEffect(() => {
    if (typeof window !== "undefined" && window.innerWidth < 1024) {
      setIsSidebarOpen(false);
    }
  }, [pathname]);


  return (
    <div className="flex h-[100dvh] bg-slate-50 dark:bg-slate-900/50 dark:bg-slate-950 overflow-hidden" dir="rtl">


      <CharitySidebar 
        charityName={charityName} 
        logoUrl={logoUrl} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen}
        role={role}
        userType={userType}
        availableCharities={availableCharities}
        permissions={permissions}
        unreadMail={unread}
        title={title}
      />
      
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden relative">
        {/* Mobile Header (Sticky & Blur) */}
        <div className="lg:hidden sticky top-0 bg-white dark:bg-slate-800/80 backdrop-blur-lg border-b border-slate-200 dark:border-slate-700/80 h-16 flex items-center justify-between px-4 shrink-0 z-30 shadow-sm">
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsSidebarOpen(true)} 
              className="p-2 -mr-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700 dark:bg-slate-800 rounded-lg transition-colors active:scale-95"
            >
              <Menu className="w-6 h-6" />
            </button>
            <span className="font-bold text-slate-800 dark:text-slate-100 text-lg truncate max-w-[200px]" title={charityName}>
              {charityName}
            </span>
          </div>
        </div>
        
        {/* Main Content Area */}
        <main className="flex-1 overflow-y-auto w-full p-3 sm:p-4 lg:p-5 pb-20 lg:pb-5 safe-bottom">
          <div className="max-w-[1600px] mx-auto w-full">
            {children}
          </div>
        </main>
      </div>
      
      {isDeveloper && <DeveloperRoleSwitcher currentEmployeeId={currentEmployeeId} />}
    </div>
  );
}
